/* Recall items per topic. t = subtopic, k = the key point you should be able to say,
   p = priority (1 must know, 2 good to know, 3 detail), g = section in recall order (R recognise, A assess and investigate, T treat now, C complications and traps, F after and follow-up); items are listed in recall order within a section, s = source: p = the Point of Care page,
   a = ANZCOR 11.9 (Australia), b = both. sg = suggestions you can add. */
window.RECALL = {
"chest-pain": { items: [
{id:"cp2",g:"R",p:1,s:"p",t:"Chest pain: which six causes can kill, and must be excluded first?",k:"ACS, aortic dissection, PE, tension pneumothorax, tamponade, oesophageal rupture."},
{id:"cp10",g:"R",p:2,s:"p",t:"Which features of chest pain raise the chance of ACS?",k:"Pressure, exertional, eased by rest, radiation to both arms (LR about 2.6), sweating, over 20 minutes."},
{id:"cp5",g:"R",p:1,s:"p",t:"Which clues suggest aortic dissection, and what test comes before any antithrombotic?",k:"Sudden tearing pain to the back, maximal at onset, arm BP difference over 20 mmHg, pulse deficit, new AR murmur. CT aortogram before antithrombotics."},
{id:"cp1",g:"A",p:1,s:"a",t:"Chest pain: what do you do in the first 10 minutes?",k:"ECG within 10 minutes of first contact, BP in both arms, IV access, troponin, chest X-ray. ST elevation: STEMI pathway. Suspected ACS: aspirin 300 mg."},
{id:"cp3",g:"A",p:1,s:"a",t:"How does an accelerated troponin rule-out work (ADAPT)?",k:"Serial troponin in a validated protocol: ADAPT is 0 and 2 hours with TIMI 0 and no ischaemic ECG changes; 1-2 hour high-sensitivity algorithms per your hospital."},
{id:"cp11",g:"A",p:2,s:"p",t:"Why is a raised troponin not the same as an MI, and what is a type 2 MI?",k:"Injury is above the 99th percentile; MI needs ischaemia too. Type 2 MI: supply and demand mismatch. Look at the rise and fall."},
{id:"cp4",g:"A",p:1,s:"a",t:"Who counts as low risk for ACS in Australia and needs no further coronary testing?",k:"Under 40, atypical symptoms, no known CAD, normal troponin and ECG, symptom-free: no further coronary testing."},
{id:"cp7",g:"A",p:2,s:"a",t:"Intermediate-risk chest pain: how soon should non-invasive testing happen?",k:"Non-invasive testing ideally within 7 days, acceptable up to 14."},
{id:"cp13",g:"A",p:3,s:"p",t:"What are the contraindications to a stress test?",k:"Acute MI or unstable angina, uncontrolled arrhythmia, PE, severe aortic stenosis, myocarditis or pericarditis, dissection."},
{id:"cp6",g:"C",p:1,s:"p",t:"Why can't the history rule out ACS, and does a GTN response prove cardiac pain?",k:"Atypical presentations in women, older people and diabetes. GTN response does not prove cardiac pain."},
{id:"cp8",g:"C",p:2,s:"b",t:"When must you not give GTN?",k:"Low BP, inferior MI with RV involvement (do V4R), recent PDE-5 inhibitor (sildenafil 24 hours; tadalafil longer)."},
{id:"cp9",g:"T",p:2,s:"a",t:"Chest pain: when do you give oxygen, and what is the target in COPD?",k:"Only if saturations are under 93% (88-92% target in COPD)."},
{id:"cp12",g:"T",p:3,s:"p",t:"Which non-cardiac causes of chest pain are common, and how is each treated?",k:"Costochondritis (analgesia), reflux (PPI), pill oesophagitis, shingles (antiviral), biliary colic (ultrasound, LFTs), panic (exclusion)."}
], sg: [
{id:"cps2",g:"R",p:3,s:"p",t:"What is Boerhaave syndrome: how does it present and what do you do?",k:"Pain after forceful vomiting, sometimes surgical emphysema; CT, nil by mouth, surgical review. (My suggestion.)"},
{id:"cps1",g:"A",p:2,s:"p",t:"What are the five HEART score components, and what are the risk bands?",k:"History, ECG, Age, Risk factors, Troponin, each 0-2. Low (0-3), moderate (4-6), high (7-10). (My suggestion from standard teaching.)"}
]},

"acs-and-mi": { items: [
{id:"mi1",g:"R",p:1,s:"p",t:"What are the ECG criteria for STEMI, including the STEMI equivalents?",k:"ST elevation 1 mm or more in two contiguous leads; V2-V3 2 mm men, 1.5 mm women. Also posterior (ST depression V1-V4), aVR elevation with widespread depression, new LBBB with symptoms."},
{id:"mi13",g:"R",p:2,s:"p",t:"Type 1 vs type 2 MI: what causes each, and how do you treat type 2?",k:"Type 1: plaque rupture. Type 2: supply and demand mismatch (sepsis, fast AF, anaemia, PE). Treat the cause."},
{id:"mi7",g:"A",p:1,s:"a",t:"NSTEACS: how soon should angiography happen for very high, high and intermediate risk?",k:"Very high risk within 2 hours; high (GRACE over 140, dynamic changes, troponin rise) within 24 hours; intermediate (GRACE 109-140) within 72 hours."},
{id:"mi6",g:"C",p:1,s:"p",t:"How does an RV infarct present, which lead confirms it, and how do you treat it?",k:"Inferior STEMI with low BP, raised JVP, clear lungs; ST elevation in V4R. Fluid, avoid GTN."},
{id:"mi8",g:"C",p:1,s:"p",t:"Which mechanical complications follow MI, how do they present, and what do you do?",k:"New murmur with pulmonary oedema or shock: papillary muscle or septal rupture. Sudden tamponade: free wall rupture. Urgent echo and surgery."},
{id:"mi15",g:"C",p:3,s:"p",t:"Low BP after angiography: what are the causes, and what do you do?",k:"Think bleeding (groin or retroperitoneal), re-infarction, tamponade, arrhythmia. Fluid, ECG, Hb, bedside echo, call cardiology."},
{id:"mi14",g:"C",p:3,s:"p",t:"Pericarditis after MI: what do you give, and what do you avoid?",k:"Aspirin and colchicine; avoid other NSAIDs early after MI."},
{id:"mi4",g:"T",p:1,s:"a",t:"Aspirin in ACS: what is the loading dose and the maintenance dose?",k:"300 mg chewed or dissolved, then 100-150 mg daily."},
{id:"mi5",g:"T",p:1,s:"a",t:"Which P2Y12 inhibitor, at what doses, and when is clopidogrel the choice?",k:"Ticagrelor 180 then 90 twice daily, or prasugrel 60 then 10 daily (not over 75, under 60 kg, prior stroke or TIA). Clopidogrel 300-600 then 75 with lysis or oral anticoagulation."},
{id:"mi9",g:"T",p:2,s:"a",t:"ACS anticoagulation: which drugs, and what must you not do?",k:"Unfractionated heparin or enoxaparin (enoxaparin may be preferred). Do not switch between them."},
{id:"mi10",g:"T",p:2,s:"a",t:"ACS: when do you give oxygen?",k:"Only if saturations are under 93%."},
{id:"mi2",g:"T",p:1,s:"a",t:"STEMI within 12 hours: when primary PCI, when fibrinolysis?",k:"Within 12 hours: primary PCI if within 90 minutes of first medical contact, otherwise fibrinolysis if no contraindications."},
{id:"mi3",g:"T",p:1,s:"a",t:"How do you recognise failed lysis, what do you do, and when is angiography after successful lysis?",k:"ST resolution 50% or less at 60-90 minutes, or instability: transfer for rescue PCI. After successful lysis: angiography within 24 hours."},
{id:"mi11",g:"F",p:2,s:"a",t:"What is the secondary prevention after MI?",k:"Aspirin indefinitely, DAPT up to 12 months, highest tolerated statin (LDL under 1.8), beta-blocker if EF 40% or less, ACE inhibitor where indicated, cardiac rehab for all."},
{id:"mi12",g:"F",p:2,s:"a",t:"ACS in a patient with AF: which antiplatelet goes with the anticoagulant, and how long is triple therapy?",k:"Clopidogrel with the oral anticoagulant; keep triple therapy short."}
], sg: [
{id:"mis1",g:"T",p:2,s:"p",t:"What are the contraindications to fibrinolysis?",k:"Any prior intracranial haemorrhage, ischaemic stroke within 3 months, active bleeding, suspected dissection, recent head trauma or neurosurgery. (My suggestion from standard teaching; check your protocol.)"},
{id:"mis2",g:"F",p:3,s:"p",t:"When is CABG chosen over PCI?",k:"Left main, three-vessel, or two-vessel disease including the proximal LAD."}
]},

"pericarditis": { items: [
{id:"pc12",g:"R",p:3,s:"p",t:"What is the commonest cause of pericarditis, and what is its usual course?",k:"Viral (coxsackie B). Usually self-limiting."},
{id:"pc1",g:"R",p:1,s:"p",t:"Pericarditis: what are the four diagnostic criteria (two needed)?",k:"Pleuritic pain better leaning forward, friction rub, widespread concave ST elevation with PR depression, new or worse effusion (ESC criteria)."},
{id:"pc2",g:"R",p:1,s:"p",t:"On ECG, how do you tell pericarditis from STEMI, and what if in doubt?",k:"Pericarditis: widespread, concave, PR depression, reciprocal change only in aVR. STEMI: territorial, reciprocal depression, Q waves. In doubt: treat as STEMI."},
{id:"pc10",g:"R",p:2,s:"p",t:"What are the four ECG stages of pericarditis?",k:"1 ST elevation, 2 back to baseline in about a week, 3 T inversion, 4 normal over weeks to months."},
{id:"pc3",g:"A",p:1,s:"p",t:"Pericarditis: which high-risk features mean admission?",k:"Fever, high white cells, effusion over 2 cm, tamponade signs, raised troponin, immunocompromised, anticoagulated, trauma, NSAID failure."},
{id:"pc6",g:"C",p:1,s:"p",t:"Early post-MI pericarditis: what do you give, and what do you avoid?",k:"Aspirin plus colchicine. Avoid other NSAIDs and steroids early after MI."},
{id:"pc11",g:"C",p:2,s:"p",t:"What is Dressler syndrome, and when does it occur?",k:"Autoimmune pericarditis weeks to months after MI or cardiac surgery."},
{id:"pc5",g:"T",p:1,s:"b",t:"Pericarditis: which NSAID, what dose, how long, and when aspirin instead?",k:"Ibuprofen with food at the lowest effective dose (Australian review: 400 mg three times daily; US page 600-800 mg), tapered once symptoms and CRP settle. Aspirin instead after MI or with CAD."},
{id:"pc4",g:"T",p:1,s:"a",t:"Pericarditis: what colchicine dose, for how long, and what does it do?",k:"0.5 mg twice daily for 3 months (Australian tablets are 0.5 mg; once daily if under 70 kg). Halves recurrence."},
{id:"pc9",g:"T",p:2,s:"a",t:"Pericarditis on NSAIDs: who needs PPI cover?",k:"Over 65, previous ulcer, or on aspirin, steroids or anticoagulants."},
{id:"pc7",g:"T",p:2,s:"p",t:"Pericarditis: when are steroids used, what is their downside, and when never?",k:"Second line: NSAID failure or contraindication, autoimmune, uraemic. They increase recurrence. Never in bacterial pericarditis."},
{id:"pc8",g:"F",p:2,s:"a",t:"After pericarditis: when can they return to exercise and competitive sport?",k:"No strenuous exercise until symptoms resolve and ECG and CRP normalise; competitive athletes at least 3 months."}
], sg: [
{id:"pcs2",g:"C",p:3,s:"p",t:"What is myopericarditis, and how is its management different?",k:"Pericarditis with raised troponin: admit, echo, cardiology, longer exercise restriction."},
{id:"pcs1",g:"T",p:2,s:"p",t:"Which drugs interact with colchicine, and when do you reduce the dose?",k:"Clarithromycin, some azoles, verapamil, ciclosporin; reduce in kidney impairment. (My suggestion from standard teaching.)"}
]},

"pericardial-effusion-and-tamponade": { items: [
{id:"tm1",g:"R",p:1,s:"p",t:"Tamponade: why does the speed of fluid collection matter more than its size?",k:"A small effusion that collects fast (after a procedure) can cause tamponade; a large slow one may not."},
{id:"tm2",g:"R",p:1,s:"p",t:"Which signs of tamponade are most useful, and which are late?",k:"Breathlessness, tachycardia, raised JVP, pulsus paradoxus over 10 mmHg. Low BP and Beck triad are late and insensitive."},
{id:"tm7",g:"R",p:2,s:"p",t:"How do you measure pulsus paradoxus with a cuff, and what value is significant?",k:"Pressure where sounds appear only in expiration minus pressure where they are heard throughout. Over 10 mmHg is pulsus; under 10 makes tamponade very unlikely."},
{id:"tm11",g:"R",p:3,s:"p",t:"Tamponade: what do the ECG and chest X-ray show?",k:"Electrical alternans (16-21%), low voltage. Big globular heart on X-ray."},
{id:"tm3",g:"A",p:1,s:"p",t:"What are the echo signs of tamponade?",k:"Effusion, RV diastolic collapse, RA systolic collapse, plethoric IVC, swinging heart."},
{id:"tm8",g:"A",p:2,s:"p",t:"What are the causes of pericardial effusion?",k:"Procedures, pericarditis, cancer (lung, breast, lymphoma), uraemia, hypothyroidism, autoimmune, radiation, blood."},
{id:"tm9",g:"A",p:2,s:"p",t:"Which tests do you send on pericardial fluid?",k:"Cell count, protein, LDH, Gram stain and culture, TB tests, cytology."},
{id:"tm10",g:"C",p:2,s:"p",t:"After cardiac surgery: what suggests clot tamponade, and what do you do?",k:"Drains suddenly stop, BP falls, CVP rises: clot tamponade. Call the surgeon; re-opening may be needed."},
{id:"tm4",g:"T",p:1,s:"p",t:"What is the definitive treatment for tamponade?",k:"Pericardiocentesis. Do not delay it in an unstable patient."},
{id:"tm5",g:"T",p:1,s:"p",t:"Tamponade: which treatments must you avoid, and why is intubation risky?",k:"Diuretics, vasodilators, and intubation if at all possible (positive pressure lowers venous return)."},
{id:"tm6",g:"T",p:1,s:"p",t:"Haemopericardium from dissection, free wall rupture or trauma: who fixes it?",k:"Dissection, free wall rupture or trauma: cardiothoracic surgery, not just a needle."}
], sg: [
{id:"tms1",g:"F",p:2,s:"p",t:"Recurrent malignant effusion: what is the option?",k:"Consider a pericardial window, matched to goals of care."}
]},

"hypertensive-urgency-and-emergency": { items: [
{id:"ht1",g:"R",p:1,s:"p",t:"Hypertensive urgency vs emergency: what BP, and what separates them?",k:"Both usually over 180/120. Emergency = organ damage (brain, eyes, heart, aorta, kidneys, blood). Urgency = none; mild headache allowed."},
{id:"ht7",g:"R",p:1,s:"p",t:"High BP in pregnancy over 20 weeks or postpartum: what do you assume, and who do you call?",k:"Over 20 weeks or postpartum with high BP: pre-eclampsia until proven otherwise. Call obstetrics."},
{id:"ht2",g:"A",p:1,s:"p",t:"The ward call for high BP: what do you do?",k:"See the patient, re-measure properly, look for organ damage, treat pain, retention, anxiety and missed tablets. No IV drugs for a well patient."},
{id:"ht8",g:"A",p:2,s:"p",t:"Hypertensive emergency: what is the organ-damage work-up?",k:"ECG, troponin, creatinine, urinalysis, FBC and film (MAHA), chest X-ray, fundoscopy, CT head if neurological, CT aortogram if dissection suspected."},
{id:"ht12",g:"C",p:3,s:"p",t:"What is PRES: how does it present, and where does the MRI show change?",k:"Headache, seizures, confusion, visual loss; MRI shows parieto-occipital oedema."},
{id:"ht3",g:"T",p:1,s:"p",t:"Hypertensive emergency: how fast do you lower BP, and why not faster?",k:"No more than 25% in the first hour, then about 160/100 over 2-5 hours, then normal over days. Too fast causes stroke and kidney injury."},
{id:"ht9",g:"T",p:2,s:"p",t:"Hypertensive urgency: what are the BP targets and the plan?",k:"Under 160/100 over hours, then under 130/90 over days, with oral drugs and GP follow-up."},
{id:"ht10",g:"T",p:2,s:"p",t:"Hypertensive emergency: which IV drugs, and what caution for each?",k:"Labetalol (bolus or infusion), GTN infusion, hydralazine (unpredictable). Nicardipine is not stocked everywhere in Australia: check your formulary."},
{id:"ht4",g:"T",p:1,s:"p",t:"Dissection: which drug first, what targets, and what must you never give alone?",k:"Beta-blocker first (labetalol or esmolol); systolic under 120 and heart rate under 60 within an hour. Never a vasodilator alone."},
{id:"ht5",g:"T",p:1,s:"p",t:"Hypertension with ACS or pulmonary oedema: which drug, what target, and which drug to avoid?",k:"GTN; systolic under 140 within an hour. Avoid beta-blockers in pulmonary oedema or shock."},
{id:"ht6",g:"T",p:1,s:"p",t:"Stimulant toxicity with high BP: what first, what to avoid, and who to call?",k:"Benzodiazepines first; avoid a beta-blocker alone. Call the Poisons Information Centre 13 11 26."},
{id:"ht11",g:"F",p:2,s:"p",t:"What are the secondary causes of hypertension?",k:"Drugs (NSAIDs, steroids, pill, stimulants), sleep apnoea, renal artery stenosis, primary aldosteronism, phaeochromocytoma, thyroid, Cushing, coarctation."}
], sg: [
{id:"hts1",g:"C",p:2,s:"p",t:"Why not give sublingual nifedipine?",k:"Unpredictable, sometimes severe BP drops. (My suggestion from standard teaching.)"}
]},

"syncope-and-loss-of-consciousness": { items: [
{id:"sy1",g:"R",p:1,s:"p",t:"What is syncope, and which mimics must you exclude first?",k:"Brief LOC from low brain blood flow with fast full recovery. Exclude hypoglycaemia, hypoxia, intoxication, seizure, stroke."},
{id:"sy4",g:"R",p:1,s:"p",t:"What are the three kinds of syncope, how common is each, and what if unclear?",k:"Reflex (about 60%), orthostatic (15%), cardiac (15%). If reflex or orthostatic is not clear: think cardiac."},
{id:"sy11",g:"R",p:3,s:"p",t:"Seizure vs syncope: which feature points to seizure, and which don't help?",k:"Prolonged confusion afterwards suggests seizure. Tongue biting and incontinence occur in both."},
{id:"sy2",g:"A",p:1,s:"p",t:"What are the red flags for cardiac syncope (including the family history)?",k:"Exertional or supine, no warning, palpitations, chest pain, breathlessness, heart disease, abnormal ECG, family history of sudden death."},
{id:"sy-h1",g:"A",p:1,s:"p",from:["h1794306715277"],t:"What are the can't-miss causes of syncope?",k:"Arrhythmia, aortic stenosis, PE, bleeding (GI bleed, ruptured AAA, ectopic pregnancy), seizure, stroke."},
{id:"sy3",g:"A",p:1,s:"p",t:"Syncope: what do you look for on the ECG?",k:"Heart block or pauses, long QT, delta wave (WPW), Brugada, HCM voltages, ARVC epsilon wave, ischaemia, new arrhythmia."},
{id:"sy6",g:"A",p:1,s:"p",t:"How do you do lying and standing BP, and what fall is orthostatic hypotension?",k:"Lying, immediately on standing, and at 3 minutes. Fall of 20 systolic or 10 diastolic is orthostatic hypotension."},
{id:"sy7",g:"A",p:2,s:"p",t:"Syncope: which tests does everyone get?",k:"ECG, glucose, FBC, electrolytes, troponin; telemetry if admitted. Pregnancy test in women of child-bearing age."},
{id:"sy8",g:"A",p:2,s:"p",t:"Syncope: when do you order an echo, when a CT head, and is carotid Doppler useful?",k:"Echo for a murmur, heart disease or abnormal ECG. CT head for head strike with anticoagulants or focal signs. Carotid Doppler rarely helps."},
{id:"sy9",g:"A",p:2,s:"p",t:"What are the causes of orthostatic hypotension?",k:"Diuretics, vasodilators, alpha-blockers, beta-blockers, dehydration, autonomic failure (Parkinson disease, diabetes, amyloid)."},
{id:"sy10",g:"T",p:2,s:"p",t:"How do you treat reflex, orthostatic and cardiac syncope?",k:"Reflex: education, counter-pressure. Orthostatic: stop culprit drugs, fluids, stockings; midodrine or fludrocortisone by specialist. Cardiac: treat the cause."},
{id:"sy5",g:"F",p:1,s:"a",t:"Syncope and private driving (Austroads): what are the rules?",k:"Typical vasovagal unlikely while driving: fit. Single blackout of uncertain cause: 6 months. Two or more over 24 hours apart: 12 months. Licensing authority decides."}
], sg: [
{id:"sys1",g:"R",p:2,s:"p",t:"Which bleeding causes can present as syncope?",k:"Melaena, ruptured AAA, ectopic pregnancy can present as syncope. (My suggestion.)"}
]},

"acute-decompensated-heart-failure": { items: [
{id:"hf3",g:"R",p:1,s:"p",t:"ADHF: what do you do for warm-wet, warm-dry, cold-wet and cold-dry?",k:"Warm and wet: IV diuretic (most common). Warm and dry: look for another cause. Cold and wet: shock, ICU. Cold and dry: senior review, stop diuretics, consider cautious fluid."},
{id:"hf1",g:"R",p:1,s:"b",t:"How do you spot cardiogenic shock, and what do you do straight away?",k:"Systolic under 90 for over 30 minutes, cold and clammy, narrow pulse pressure, confusion, rising lactate, poor urine. Call your senior and ICU; stop the beta-blocker and vasodilators."},
{id:"hf14",g:"R",p:2,s:"p",t:"ADHF: what NT-proBNP rules it out, and which exam and X-ray findings are most useful?",k:"NT-proBNP under 300 makes ADHF unlikely. S3 (LR 11) and JVP (LR 5) are the most useful signs; crackles are not specific. Oedema on CXR has LR 12."},
{id:"hf9",g:"A",p:1,s:"p",t:"What are the common triggers of decompensated heart failure?",k:"Salt, fluid and missed tablets; ischaemia; arrhythmia (AF); hypertension; NSAIDs, steroids, verapamil or diltiazem; infection; kidney injury; alcohol or cocaine; valve disease; iatrogenic IV fluid."},
{id:"hf6",g:"C",p:1,s:"p",t:"Creatinine rising during diuresis: what does it usually mean, what do you do, and which two blood results tell you diuresis is going well?",k:"Usually haemodynamic, not kidney damage: with less fluid in the circulation the kidney filters under slightly lower pressure, so creatinine creeps up. If still congested, keep diuresing and trust the exam. Going well (the sweet spot): bicarbonate rising, because salt water is leaving and the bicarbonate left behind is more concentrated (a contraction alkalosis), with creatinine stable or only a little up. Worry if creatinine keeps climbing while they look dry, the BP falls or the urine output drops: discuss with your senior."},
{id:"hf10",g:"C",p:2,s:"p",from:["h1794380007689"],t:"Diuretic resistance on furosemide 80 mg IV twice daily: what are the next steps, and why check K before acetazolamide?",k:"Still not enough urine on furosemide 80 mg IV twice daily: call cardiology, then try a furosemide infusion, add a thiazide (metolazone), or add acetazolamide if alkalotic and K above 4 (ADVOR). Check K first because acetazolamide wastes potassium like the loops. Not verified: the K above 4 cut-off is from the Point of Care page and could not be checked against the Australian Diamox product information. Confirm with your hospital protocol."},
{id:"hf11",g:"C",p:2,s:"p",dup:"hfd5",t:"Potassium and magnesium",k:"Check daily and replace early; loop diuretics waste both. Keep spironolactone going to hold potassium."},
{id:"hf8",g:"C",p:1,s:"a",from:["h1794380073094"],t:"In hospital, when do you hold or reduce ARNI, ACE inhibitor, ARB, MRA and beta-blocker?",k:"ARNI, ACE inhibitor, ARB or MRA: caution if systolic under 95, K over 5.0 or eGFR under 20; reduce if K 5.5-6.0, withhold if over 6.0. Beta-blocker: caution if HR under 55 or systolic under 95."},
{id:"hf2",g:"T",p:1,s:"b",t:"Acute pulmonary oedema: what are the first steps, and what do you avoid?",k:"Sit up, oxygen if hypoxic, CPAP or NIV if oxygen is not enough or CO2 rises, GTN if BP allows (infusion from about 5-10 mcg/min), IV furosemide. Avoid morphine."},
{id:"hf4",g:"T",p:1,s:"p",t:"ADHF: what starting dose of IV loop diuretic?",k:"About twice the home oral dose, given IV (higher with kidney disease). An Australian ED handbook gives furosemide 80 mg IV, or the usual dose IV."},
{id:"hf5",g:"T",p:1,s:"p",t:"After the first IV diuretic dose: what do you check at 1 hour and at 3-4 hours, and what do you do?",k:"Urine within an hour, or check for shock and double the dose. At 3-4 hours, less than halfway to goal: double; otherwise repeat. Second dose by early afternoon."},
{id:"hf7",g:"T",p:1,s:"a",t:"What are the four pillars for HFrEF, and when do you start them?",k:"ARNI preferred (or ACE inhibitor, 36-hour washout before ARNI; ARB last-line), a proven beta-blocker (bisoprolol, carvedilol, metoprolol succinate, nebivolol), MRA, SGLT2 inhibitor (dapagliflozin or empagliflozin). Start all as soon as clinically possible."},
{id:"hf12",g:"F",p:2,s:"a",t:"Heart failure: what are the IV iron criteria, which iron, and why not oral?",k:"Ferritin under 100 µg/L, or 100-299 with TSAT under 20%: IV ferric carboxymaltose. Oral iron does not work in heart failure."},
{id:"hf13",g:"F",p:2,s:"a",t:"ADHF: what is the discharge plan?",k:"Oral diuretic when symptoms and JVP improve, ideally tested for 24 hours. Daily weights: 2 kg change in 2 days, contact the GP within 24 hours. Review within 1-2 weeks. Uptitrate the pillars at least twice before discharge."},
{id:"hf15",g:"F",p:3,s:"p",t:"Heart failure devices: how long after full medical therapy, and who gets an ICD or CRT?",k:"After 3-6 months of full therapy: ICD if EF under 35% (US criteria); CRT if EF under 35% with QRS over 150 ms, especially LBBB. Cardiology decides."},
{id:"hfd1",g:"T",p:2,s:"n",t:"Where does each diuretic class act, and how much sodium is taken back at each site?",k:"Proximal tubule: acetazolamide (about 65% of sodium taken back). Thick limb of the loop: loop diuretics (about 25%, the strongest). Distal tubule: thiazides (about 5%). Collecting duct: spironolactone (about 3-5%). Block one part and the later parts take back more. (Percentages are standard physiology, not from an Australian source.)"},
{id:"hfd2",g:"T",p:1,s:"n",t:"Why give furosemide IV in congestion, and how fast can you push it?",k:"Oral absorption is unpredictable (Australian product information: mean about 60% in healthy men, wide spread between people) and a swollen gut absorbs less. IV starts in about 5 minutes; oral in about 1 hour. Steep dose-response: below a threshold dose nothing happens, and kidney disease raises the threshold. IV rate no faster than 4 mg/minute (hearing)."},
{id:"hfd3",g:"T",p:2,s:"n",t:"Furosemide, bumetanide and torasemide: how long do they last, how do doses compare, and what is available in Australia?",k:"Furosemide: half-life up to about 100 minutes (longer in kidney or liver disease); oral lasts 6-8 hours, IV about 2 hours. Bumetanide: absorbed almost completely, half-life about 1 hour (your notes); about 1 mg bumetanide equals 40 mg oral furosemide, and oral furosemide is roughly half as potent as IV (standard teaching); registered in Australia (Burinex) but not PBS-listed for heart failure. Torasemide: half-life about 3-6 hours, once daily (your notes); I could not confirm it is marketed in Australia, so check your hospital."},
{id:"hfd4",g:"T",p:2,s:"n",t:"Thiazides in heart failure: how strong are they, when do they work poorly, and when are they used?",k:"Distal tubule, weaker than loops, poor at low GFR. An add-on for diuretic resistance, not routine (Medicine Today July 2026: hydrochlorothiazide 12.5-25 mg daily; metolazone not PBS-listed for heart failure). Chlorthalidone (Hygroton) appears in the Australian medicines listing but I could not confirm availability; check your hospital protocol."},
{id:"hfd5",g:"C",p:1,s:"n",t:"Which electrolytes do loop diuretics waste, what acid-base change follows, and how do you protect against it?",k:"They lose sodium, potassium, chloride, calcium, magnesium and hydrogen: low potassium and magnesium, and a contraction alkalosis. They do not retain potassium or hydrogen. Check K and Mg daily and replace early, and keep spironolactone going to hold potassium."},
{id:"hfd6",g:"C",p:1,s:"n",from:["h1794378706339","h1794378710046"],t:"Thiazides vs spironolactone: what does each do to potassium, acid-base and sodium?",k:"Thiazides lose potassium and hydrogen (low K, alkalosis) and are the classic drug cause of hyponatraemia; they keep calcium (useful in calcium stones). Spironolactone blocks aldosterone: keeps potassium and hydrogen, so high K and metabolic acidosis, and can add to low sodium. It improves survival in HFrEF; check K and creatinine."},
{id:"hfd7",g:"C",p:2,s:"n",from:["h1794378583887"],t:"Acetazolamide: how does it work, what acid-base change does it cause, and when is it added in heart failure?",k:"Blocks carbonic anhydrase in the proximal tubule: loses bicarbonate and sodium, so a metabolic acidosis. In heart failure an add-on when loops are not enough (ADVOR), especially if alkalotic; not a starter. Medicine Today lists 250-500 mg daily."},
{id:"hfd8",g:"C",p:1,s:"n",from:["h1794378605510"],t:"Why do diuretics stop working, and what is the fix for each reason?",k:"Braking: the drug wears off and the kidney grabs sodium back, so give doses more often or as an infusion. Downstream catch-up: block one segment and later ones take back more, so add a second class (thiazide, spironolactone or acetazolamide). Poor gut absorption: give IV. Poor kidney function: higher threshold dose. Acetazolamide is not the long-acting fix for braking; it is a second site of action."}
], sg: [
{id:"hfs1",g:"R",p:2,s:"p",t:"What are the EF cut-offs for HFrEF, HFmrEF and HFpEF, and where are the pillars proven?",k:"EF 40% or less, 41-49%, and 50% or more. The four pillars are proven in HFrEF; empagliflozin should also be considered in HFmrEF and HFpEF."},
{id:"hfs2",g:"A",p:2,s:"p",t:"New heart failure: what is the work-up for ischaemic and non-ischaemic causes?",k:"Ischaemic: ECG, troponin, stress test or angiogram. Non-ischaemic: lipids, HbA1c, iron studies, TSH, and others by suspicion; cardiac MRI if unclear."},
]},

"aortic-dissection": { items: [
{id:"ad3",g:"R",p:1,s:"p",t:"How does aortic dissection present, and what are the can't-miss signs?",k:"Tearing chest or back pain, aortic regurgitation murmur, pulse deficit, arm BP difference over 20 mmHg."},
{id:"ad9",g:"R",p:2,s:"p",t:"What are the risk factors for aortic dissection, and what do you think of under 40?",k:"Hypertension in about 70%. Under 40: think Marfan, connective tissue disease, bicuspid valve. Also smoking and family history."},
{id:"ad1",g:"R",p:1,s:"p",t:"Type A vs type B dissection: what is involved, and what does each need?",k:"Type A involves the ascending aorta: urgent surgical repair. Type B is descending only: usually medical, TEVAR if complicated."},
{id:"ad10",g:"A",p:2,s:"p",t:"Aortic dissection: what is the first-hour work-up?",k:"Telemetry; FBC, UEC, coags, troponin, D-dimer, group and hold; ECG, CXR, CT aortogram, echo. Serial BP in both arms, consider an arterial line."},
{id:"ad4",g:"A",p:1,s:"p",t:"Aortic dissection: which test is best, and what can D-dimer, CXR and ECG not do?",k:"CTA is the most sensitive and specific. D-dimer has a high negative predictive value but cannot fully rule it out. CXR widened mediastinum in about a third. ECG often normal."},
{id:"ad7",g:"C",p:2,s:"p",t:"What are the complications of type A dissection?",k:"Coronaries (MI), aortic valve (regurgitation), carotids (stroke), tamponade."},
{id:"ad8",g:"C",p:2,s:"p",t:"Complicated type B dissection: which branch vessels are affected, how does each present, and what is needed?",k:"Renal (oliguria, failure), mesenteric (celiac), spinal (leg weakness, paraplegia), distal occlusion (Leriche). These need TEVAR."},
{id:"ad5",g:"T",p:1,s:"p",t:"Aortic dissection: who do you call, and when do you involve haematology?",k:"Cardiothoracic surgery urgently. Involve haematology early if on anticoagulation (reversal may be needed)."},
{id:"ad12",g:"T",p:3,s:"p",t:"Aortic dissection: how do you control the pain?",k:"IV morphine. The page gives no dose, so use your protocol."},
{id:"ad2",g:"T",p:1,s:"p",t:"Aortic dissection: what HR and BP targets, which drug first, and what must you never do?",k:"HR under 60, SBP 100-120. IV labetalol or esmolol first; add nitroprusside or nicardipine if SBP stays over 120. Never a vasodilator without a beta-blocker (reflex tachycardia raises wall stress)."},
{id:"ad6",g:"T",p:1,s:"p",t:"Low BP in aortic dissection: what do you give, what do you avoid, and what do you think of?",k:"Fluids and noradrenaline, avoid inotropes. Think tamponade."},
{id:"ad11",g:"F",p:2,s:"p",t:"After aortic dissection: what are the discharge and long-term measures?",k:"Statin, beta-blocker, low-dose aspirin. Stop smoking, control BP, avoid straining."},
{id:"ad14",g:"F",p:3,s:"p",t:"Aortic aneurysm: what size or growth means surgery, and how is it different in women?",k:"Over 5.5 cm, growth over 0.5 cm in 6 months or over 1 cm in a year. Women lower (4.5-5 cm, debated)."},
{id:"ad13",g:"F",p:3,s:"p",t:"Aortic dissection: what is the mortality for type A with and without surgery, and for type B?",k:"Type A surgery 26% mortality vs over 50% medical (IRAD 2000). Type B: 9% in hospital, 20% at 5 years."}
], sg: [
{id:"ads3",g:"R",p:3,s:"p",t:"What are DeBakey types 1, 2 and 3?",k:"1 ascending and descending, 2 ascending only, 3 descending only."},
{id:"ads2",g:"A",p:2,s:"p",t:"What does the aortic dissection risk score (ADD-RS) count, and what is it used for?",k:"Counts high-risk conditions, high-risk pain features and high-risk exam findings (0-3 points). Used to decide between D-dimer and straight to CTA. (My suggestion.)"},
{id:"ads1",g:"C",p:2,s:"p",t:"Possible dissection: why must you not give an anticoagulant or thrombolytic?",k:"They can extend the bleed. Rule dissection out before giving them to a patient with tearing pain. (My suggestion from standard teaching, not on the page.)"}
]},

"pulmonary-embolism-and-vte": { items: [
{id:"pe12",g:"R",p:2,s:"p",t:"PE risk factors: which are strong, moderate and weak, and what is Virchow's triad?",k:"Fracture or major surgery (OR over 10). OCP, hospitalised, previous VTE, cancer, sepsis (2-9). Bed rest, long travel, age, obesity, smoking, cirrhosis, CKD (under 2). Virchow: stasis, vessel injury, hypercoagulability."},
{id:"pe11",g:"R",p:2,s:"p",t:"Massive PE: why does the heart fail, and which arrest does it cause?",k:"Pressure in the RV rises, cardiac output falls, SVR rises, the septum bows into the LV and further cuts filling. Massive PE is a common cause of PEA arrest."},
{id:"pe6",g:"A",p:1,s:"p",t:"PE rule-out: how do PERC, D-dimer and imaging fit by probability, and what are the D-dimer cut-offs?",k:"Low PE probability: PERC or D-dimer. Moderate or high: imaging. D-dimer under 500 with moderate probability or under 1000 with low probability rules it out. Age-adjusted cut-off is age x 10."},
{id:"pe10",g:"A",p:2,s:"p",t:"PE: what does the ECG show, and how often?",k:"Normal in 20%. Tachycardia is the commonest (28%). T-wave inversion V1-V4, S1Q3T3 (about 8%), new RBBB, ST elevation in aVR."},
{id:"pe9",g:"A",p:2,s:"p",t:"PE: what are the signs of RV strain on echo, CT and bloods?",k:"Echo: enlarged RV, moderate or severe TR, McConnell's sign, flat septum. CT: RV/LV over 0.9. Troponin up, NT-proBNP over 500."},
{id:"pe1",g:"A",p:1,s:"p",t:"PE: what are the three risk classes, and what defines each?",k:"High: arrest or SBP under 90 not from another cause (PESI IV+). Intermediate: RV strain or troponin without hypotension (high if both, low if only one). Low: neither."},
{id:"pe14",g:"C",p:3,s:"p",t:"PE special situations: cancer, malabsorption or obesity, subsegmental PE, and a negative leg Doppler?",k:"Cancer: LMWH beats warfarin (CLOT). DOACs less reliable with malabsorption or BMI over 40. Subsegmental PE with low recurrence risk needs no anticoagulation. A negative leg Doppler does not rule out PE."},
{id:"pe4",g:"T",p:1,s:"p",t:"PE: which anticoagulant first, when do you thrombolyse, and what does heparin actually do?",k:"LMWH if stable with normal kidneys; otherwise UFH bolus and infusion. Thrombolysis only if high risk. Heparin stops new clot; the body dissolves the old clot."},
{id:"pe-rv1",g:"C",p:1,s:"p",t:"Massive PE: why can intubation kill (the three hits)?",k:"Three hits at once: positive-pressure breaths cut the blood returning to the RV, inflated lungs raise the load on the RV, and induction drugs lower the BP that feeds it. The failing RV spirals. (Standard teaching, explained in The right heart, simply.)"},
{id:"pe-rv2",g:"T",p:1,s:"p",t:"Massive PE with hypoxia: why use high-flow nasal oxygen, and what is its limit?",k:"The patient keeps breathing on their own, so there are no positive-pressure breaths and no sedation. It treats low oxygen without the three hits, but it only buys time: reperfusion is the fix."},
{id:"pe2",g:"T",p:1,s:"p",t:"Massive PE: how do you handle fluids, oxygen delivery and intubation (including the drugs)?",k:"Avoid big fluid boluses (about 500 mL at most if hypotensive): they overstretch the RV. Avoid intubation if you can: positive-pressure breaths and sedatives cut the blood returning to the RV and drop the BP, and the failing RV can collapse. Use high-flow nasal oxygen instead. If you must intubate: most experienced operator, ketamine, and a vasopressor (adrenaline or noradrenaline) ready first. (Point of Care page; the drug choices are US teaching, not verified against an Australian source.)"},
{id:"pe3",g:"T",p:1,s:"p",t:"Crashing PE (shock or arrest): who do you call, and what are the treatment options?",k:"Call the PE response team. Adrenaline (epinephrine), consider pulmonary vasodilators (NO or epoprostenol), thrombolysis or thrombectomy, and think ECMO. Pads and crash cart nearby. (Point of Care page; the drug choices are US teaching, not verified against an Australian source.)"},
{id:"pe5",g:"T",p:1,s:"p",t:"What are the absolute contraindications to tPA (strokes, surgery, trauma, bleeding)?",k:"Haemorrhagic stroke, ischaemic stroke in the last 3 months, AVM, recent brain or spine surgery, head trauma with fracture or brain injury in 3 weeks, serious active bleeding."},
{id:"pe7",g:"T",p:2,s:"p",t:"What are the relative contraindications to tPA?",k:"CNS tumour, major surgery in 2-3 weeks, platelets under 100, INR over 1.7, fibrinogen under 150, oral anticoagulant, BP over 180/110, age over 75, advanced cirrhosis."},
{id:"pe15",g:"T",p:3,s:"p",t:"What did PEITHO show about thrombolysis in intermediate-risk PE, and when do you lyse?",k:"PEITHO: in intermediate-risk PE no long-term benefit but more major bleeding and haemorrhagic stroke. Lyse in massive PE to prevent immediate death."},
{id:"pe8",g:"F",p:2,s:"p",t:"PE: what apixaban dosing, and how long do you treat provoked, unprovoked and cancer PE?",k:"Apixaban 10 mg twice daily for 7 days then 5 mg twice daily. Treat 3 months if provoked; indefinite if unprovoked with low bleeding risk, or if cancer."},
{id:"pe13",g:"F",p:2,s:"p",t:"Unprovoked PE: what is the recurrence risk, and what follow-up tests (and not) do you do?",k:"Unprovoked: about 10% recurrence in year 1 off treatment, then 5% a year. Age-appropriate cancer screening. No thrombophilia testing in the acute phase (exception: high concern for antiphospholipid syndrome)."}
], sg: [
{id:"pes3",g:"R",p:3,s:"p",t:"Which DVTs carry the PE risk, and what is May-Thurner?",k:"Iliac, femoral and popliteal clots carry the PE risk; below the knee less so. May-Thurner: left iliac vein compressed by the right iliac artery."},
{id:"pes2",g:"A",p:2,s:"p",t:"PE imaging in pregnancy or kidney disease: what is first line, and what is the alternative?",k:"CT pulmonary angiogram is first line; V/Q scan is an alternative when contrast or radiation is a problem. (My suggestion from standard teaching.)"},
{id:"pes1",g:"T",p:1,s:"p",t:"Where must you check PE anticoagulant dosing in Australia?",k:"Not checked against Australian guidance. Look up the current eTG regimen before you rely on the apixaban dosing above. (My suggestion.)"}
]},

"atrial-fibrillation": { items: [
{id:"af-h4",g:"A",p:1,s:"p",from:["h1794311934960"],t:"New AF: which triggers do you look for, and which bloods do you send?",k:"Look for the cause: thyroid, alcohol, sepsis, ischaemia, valve disease (also low K or Mg, PE, heart failure, recent surgery). Send TFTs, electrolytes with K and Mg, troponin and creatinine. The creatinine you send now also decides the anticoagulant dose."},
{id:"af2",g:"A",p:1,s:"p",t:"What are the CHA2DS2-VASc points?",k:"Heart failure 1, hypertension 1, age 75+ 2, diabetes 1, stroke or TIA 2, vascular disease 1, age 65-74 1, female 1."},
{id:"af1",g:"A",p:1,s:"p",t:"AF: who gets anticoagulated (CHA2DS2-VASc cut-offs)?",k:"CHA2DS2-VASc 2 or more in men, 3 or more in women (stroke risk 2% a year or more)."},
{id:"af13",g:"A",p:2,s:"p",from:["h1794308278402"],t:"AF: should a bleeding score stop anticoagulation, and which modifiable bleeding risks do you fix?",k:"Do not use a bleeding score (HAS-BLED) to withhold anticoagulation. Find and fix the modifiable risks: uncontrolled hypertension, alcohol, NSAIDs, antiplatelets, anaemia, labile INR."},
{id:"af4",g:"T",p:1,s:"p",t:"AF rate control: what heart-rate target (and with LV dysfunction), which first-line drugs, and which drug to avoid?",k:"Target under 110 (under 80 if LV dysfunction or symptoms). Beta-blocker or diltiazem/verapamil. No non-dihydropyridine CCB with moderate or severe LV systolic dysfunction."},
{id:"af5",g:"T",p:1,s:"p",t:"AF second-line rate control, and what do you do in pre-excited AF (WPW), stable vs unstable?",k:"Ordinary AF: digoxin (slow, about 2 hours) or amiodarone as backup. Pre-excited AF (WPW): no AV-nodal blockers and avoid IV amiodarone too. Unstable: synchronised shock. Stable: procainamide (RACGP); availability in your hospital not confirmed, follow your protocol."},
{id:"af8",g:"T",p:2,s:"p",t:"AF: who benefits from rhythm control?",k:"Symptomatic despite rate control, first episode, heart failure (especially HFrEF), young, athletes, patient preference."},
{id:"af-h5",g:"T",p:1,s:"b",from:["h1794310611494"],t:"Can this AF be cardioverted now: what do you do if unstable, stable under 48 hours, and stable over 48 hours?",k:"Unstable: shock now; do not wait for a TOE or anticoagulation. Stable, onset under 48 hours: cardioversion can proceed (with mild symptoms, rate control and watching is also fine). Stable, over 48 hours or unknown: exclude left atrial thrombus with TOE first, or anticoagulate for weeks (ANZCOR 11.9)."},
{id:"af6",g:"T",p:1,s:"p",t:"Electrical cardioversion of AF: how do you do it, at how many joules, and what must you never do?",k:"Sedate, anteroposterior pads, synchronise to the QRS, start about 100 J biphasic. Never defibrillate AF."},
{id:"af9",g:"T",p:2,s:"p",t:"Drug cardioversion of AF: when flecainide or propafenone, and what otherwise?",k:"Flecainide or propafenone only without structural heart disease or coronary disease. Amiodarone, dofetilide or ibutilide otherwise."},
{id:"af3",g:"F",p:1,s:"p",from:["h1794308329681"],t:"AF: which anticoagulant first line, and in which valve and kidney situations warfarin?",k:"DOAC for non-valvular AF. Warfarin (INR 2-3) for moderate to severe mitral stenosis, mechanical valves, or CrCl under 15 if apixaban not possible. Aspirin alone is not enough."},
{id:"af-h2",g:"F",p:1,s:"a",from:["h1794308325768"],t:"AF with cirrhosis: can you use a DOAC (Australian apixaban product information)?",k:"DOACs are contraindicated in cirrhosis. Australian apixaban product information: contraindicated in liver disease with coagulopathy and clinically relevant bleeding risk, including severe (Child-Pugh C); caution in mild or moderate. Check the product information for rivaroxaban and dabigatran."},
{id:"af7",g:"F",p:2,s:"p",t:"What are the DOAC doses and dose reductions in AF?",k:"Apixaban 5 mg twice daily (2.5 if two of: 80+, 60 kg or less, creatinine 1.5+). Rivaroxaban 20 mg with food (15 if CrCl 15-50). Edoxaban 60 (30). Dabigatran 150 twice daily (110). Check Australian product information."},
{id:"af14",g:"F",p:3,s:"b",t:"AF after PCI: what antithrombotics, for how long, and what at 12 months?",k:"Why: the stent needs antiplatelets and the AF needs an anticoagulant, but all three together raise bleeding a lot. So stop aspirin early (US page 1-4 weeks; Australian review about 1 month) and keep the anticoagulant plus a P2Y12 inhibitor. Clopidogrel preferred over ticagrelor or prasugrel; DOAC preferred over warfarin. At 12 months stop the antiplatelet and keep the anticoagulant alone (NHFA/CSANZ 2018 via Medicine Today 2019; check eTG)."},
{id:"af10",g:"F",p:2,s:"p",t:"Which drugs keep sinus rhythm in AF, and what are the cautions?",k:"Class Ic (avoid in CAD or structural disease), amiodarone, sotalol, dofetilide, dronedarone. No antiarrhythmic in advanced conduction disease without pacing."},
{id:"af11",g:"F",p:2,s:"p",t:"AF catheter ablation: what is done, who does best, and what about anticoagulation after?",k:"Pulmonary vein isolation. Works best in paroxysmal AF (70-80%), heart failure, young symptomatic patients. Keep anticoagulation based on the score, not the rhythm."},
{id:"af12",g:"F",p:2,s:"p",t:"AF: which risk factors do you modify, and with what targets?",k:"Weight loss 10% or more, exercise 210 minutes a week, BP under 130/80, treat sleep apnoea, alcohol under 3 drinks a week, stop smoking, glycaemic control. Caffeine restriction not advised."},
{id:"af-h1",g:"C",p:1,s:"p",from:["h1794308709478"],t:"Why give an AV-nodal blocker before flecainide, and when must you not?",k:"Flecainide slows the atria (flutter about 300 to 220) so the AV node can now pass every beat 1 to 1, and the ventricles race at about 220. Give the AV-nodal blocker first. Only in ordinary AF or flutter: in pre-excited AF give none."},
{id:"af-h3",g:"C",p:1,s:"p",from:["h1794310065418"],t:"Pre-excited AF: why are AV-nodal blockers dangerous, which drugs do you avoid, and what if unstable?",k:"The AV node has a speed limiter; the accessory pathway (delta wave) does not. Blocking the node sends the fast atrial rate down the accessory pathway and the ventricles can go dangerously fast. Avoid beta-blockers, verapamil, diltiazem and digoxin; if unstable, synchronised shock."},
{id:"af15",g:"F",p:3,s:"p",t:"AF burden: how long an episode carries stroke risk, and when is risk highest?",k:"Episodes over 17-24 hours carry significant risk. Over twofold risk from 1 hour. Risk highest in the 5 days after an episode."}
], sg: [
{id:"afs1",g:"T",p:1,s:"a",t:"Unstable AF: which signs, and what is the treatment?",k:"Adverse signs (low BP, chest pain, heart failure, confusion, very fast rate) mean cardioversion with sedation, not drugs first (ANZCOR 11.9)."},
{id:"afs4",g:"R",p:2,s:"p",t:"Why does the QRS width change beat to beat in pre-excited AF?",k:"Some beats go down the AV node (narrower QRS) and some down the accessory pathway (wider QRS), so the width changes beat to beat and the rhythm is irregular. (My suggestion.)"},
{id:"afs3",g:"T",p:2,s:"b",t:"Where do you find the Australian version of the AF rate-control order?",k:"Open the AF Study Kit (Australia first) in this app: it compares the US page with Australian guidance."}
]},

"bradycardia": { items: [
{id:"br13",g:"R",p:3,s:"p",t:"Bradycardia: what rate defines it, when do symptoms start, and what are sick sinus, junctional and physiological bradycardia?",k:"Bradycardia is under 60 but symptoms usually start under 50. Sick sinus syndrome is SA node dysfunction. Junctional rhythm starts in the AV node. Athletes and sleep can be physiological."},
{id:"br7",g:"R",p:1,s:"p",t:"What are the four heart blocks, and how does the PR behave in each?",k:"First degree: long fixed PR. Mobitz I: PR lengthens then a drop. Mobitz II: fixed PR, sudden drops. Complete: atria and ventricles independent."},
{id:"br-h1",g:"R",p:2,s:"p",from:["h1794313233298"],t:"Complete heart block: what sets the beat, and how do junctional and ventricular escape differ?",k:"Nothing gets through, so a backup pacemaker below the block sets the beat. The higher the backup, the better. Block at the AV node: junctional escape, 40-60 a minute, narrow QRS, steadier. Block in the wires below: ventricular escape, 20-40 a minute, wide QRS, unreliable (LITFL)."},
{id:"br1",g:"R",p:1,s:"a",t:"Bradycardia: which adverse signs make the patient unstable?",k:"Systolic BP under 90, heart rate under 40, ventricular arrhythmia, heart failure. The US page also lists confusion, chest pain and breathlessness."},
{id:"br8",g:"R",p:1,s:"a",t:"Which bradycardia findings mark asystole risk, and what do you do even if the patient looks well?",k:"Recent asystole, Mobitz II, complete block with a broad QRS or rate under 40, a pause over 3 seconds: pads on and call cardiology even if the patient looks well."},
{id:"br11",g:"A",p:2,s:"p",t:"Bradycardia: what is the first-hour work-up?",k:"Telemetry, 12-lead ECG, FBC, UEC (with potassium), TSH, troponin, echo. Check prior ECGs, the drug chart and prior heart disease."},
{id:"br4",g:"A",p:1,s:"p",t:"Bradycardia: what are the four can't-miss causes?",k:"Acute coronary syndrome (especially inferior MI), complete heart block, beta-blocker or calcium-channel blocker toxicity, hyperkalaemia."},
{id:"br10",g:"A",p:2,s:"p",t:"Bradycardia: which reversible causes do you look for?",k:"Drugs (beta-blockers, CCBs, amiodarone, opioids, SSRIs), hyperkalaemia, hypothyroidism, hypothermia, raised intracranial pressure, infection (Lyme, endocarditis), ischaemia, vagal tone."},
{id:"br6",g:"C",p:1,s:"p",t:"When will atropine not work?",k:"Complete heart block (especially wide QRS), block below the AV node, and a transplanted heart. The page also warns about acute MI."},
{id:"br9",g:"C",p:2,s:"p",t:"Block at the AV node vs below it: why does each behave differently, and what does atropine do?",k:"The node tires gradually: its slow cells need time to reset, so each early signal passes more slowly (warning, atropine helps). The wires below are fast and all-or-none: they conduct or fail suddenly (no warning, atropine fails and can make it worse). See the Heart block pages in this app."},
{id:"br2",g:"T",p:1,s:"b",t:"Atropine for bradycardia: what dose in Australia, how often, up to what maximum, and why not too low?",k:"Australia: 500-600 mcg IV every 3-5 minutes up to 3 mg. US page says 1 mg a dose. Too low a dose can slow the heart further."},
{id:"br3",g:"T",p:1,s:"a",t:"If atropine fails: what adrenaline infusion, how do you pace, and how do you confirm capture?",k:"Adrenaline 2-10 mcg/min, or transcutaneous pacing at 70-80 a minute starting near 30 mA until capture. Capture = a QRS after every spike plus a pulse; chest twitching proves nothing."},
{id:"br5",g:"T",p:1,s:"b",t:"Beta-blocker or calcium-channel blocker toxicity: what do you give, and who do you call?",k:"Glucagon, or insulin with glucose and potassium, and much higher adrenaline doses. Call the Poisons Information Centre 13 11 26. The glucagon dose is not in the Australian source: use toxicology guidance."},
{id:"br12",g:"F",p:2,s:"p",t:"What are the indications for a permanent pacemaker?",k:"Symptomatic sinus bradycardia (with or without pauses), complete heart block, symptomatic second-degree block, syncope from bradycardia. Correct reversible causes first; involve EP."}
], sg: [
{id:"brs1",g:"A",p:2,s:"p",t:"Hyperkalaemia: what does the ECG show, and how is it treated?",k:"Peaked T, wide QRS, loss of P waves; IV calcium, insulin with glucose, per your protocol. (My suggestion from standard teaching.)"},
{id:"brs2",g:"C",p:2,s:"p",t:"Inferior MI with bradycardia: how do you treat it?",k:"Treat both together: ACS pathway, atropine reasonable, pace early, avoid nitrates when hypotensive. (My suggestion.)"},
{id:"brs4",g:"R",p:1,s:"p",t:"Mobitz I: why does the AV node tire and the PR lengthen until a beat drops?",k:"The node's slow cells need time to reset after each beat. If the next signal arrives before the reset is done, it passes slowly, so PR lengthens until one beat is blocked; the pause lets the node reset. Nothing is damaged. The sinus node sets the rate; the AV node only passes signals on. (My suggestion from standard teaching.)"},
{id:"brs5",g:"R",p:2,s:"p",t:"When does Mobitz I appear, and is it harmful?",k:"A healthy node keeps up at normal rates. Mobitz I appears when the node needs longer to reset (drugs, scarring, inferior MI, strong vagal tone: athletes, sleep) or is pushed past its limit by a very fast atrial rate. Usually benign. (My suggestion.)"},
{id:"brs6",g:"R",p:1,s:"p",t:"Mobitz II: why is there no warning, what can it progress to, and why can atropine make it worse?",k:"The wires below the node are fast and all-or-none: PR stays fixed and a beat drops suddenly. The disease often spreads, so it can progress to complete block with a slow, wide escape rhythm. Atropine speeds the node and can send more signals at a diseased wire. (My suggestion.)"},
{id:"brs7",g:"R",p:2,s:"p",t:"Why is bundle branch block not heart block, and why is the QRS wide?",k:"In BBB one branch is blocked and the other carries every signal: PR is normal and no beats drop. The QRS is wide because the blocked side is activated slowly through muscle. A wide QRS tells you the route was slow, not the cause. (My suggestion.)"},
{id:"brs8",g:"C",p:3,s:"p",t:"What is rate-related bundle branch block, and what causes it?",k:"A branch can block only at faster rates because it has not recovered in time, so the QRS goes wide as the rate rises. The cause is the fast atrial rate, not the AV node over-firing. (My suggestion.)"},
{id:"brs3",g:"T",p:3,s:"p",t:"Sedation for pacing: what does the US page suggest, and what does ANZCOR say?",k:"The US page suggests fentanyl then midazolam; ANZCOR names none. Use your hospital protocol and senior help."}
]},

"tachyarrhythmias-rapid-response": { items: [
{id:"tc1",g:"R",p:1,s:"a",t:"Tachycardia: which adverse signs mean unstable, and what is the treatment?",k:"Systolic BP under 90, heart rate over 150, chest pain, heart failure, drowsy or confused. Unstable = synchronised cardioversion with sedation."},
{id:"tc3",g:"R",p:1,s:"p",t:"Tachycardia: what goes in each of the four boxes (narrow or wide, regular or irregular)?",k:"Narrow regular: sinus, flutter, AVNRT/AVRT. Narrow irregular: AF, MAT. Wide regular: VT. Wide irregular: AF with block, pre-excited AF, torsades."},
{id:"tc10",g:"R",p:2,s:"p",t:"What are the causes of sinus tachycardia, and how do you treat it?",k:"Pain, anxiety, hypovolaemia, fever, heart failure, ACS, PE, hypoxia, alcohol withdrawal, thyroid, caffeine, drugs. Treat the cause; never shock it."},
{id:"tc11",g:"A",p:2,s:"p",t:"Tachycardia: what do you do in the first minute at the bedside?",k:"Oxygen if low, monitor, IV, pads, 12-lead ECG, bloods (K, Mg, troponin, lactate, TSH), call your senior. No pulse: arrest algorithm."},
{id:"tc7",g:"C",p:1,s:"a",t:"Pre-excited AF: which drugs do you avoid, what is safest, and what if you can't tell it from VT?",k:"No adenosine, digoxin, verapamil or diltiazem. Electrical cardioversion is usually safest. If you cannot tell VT from pre-excited AF, treat it the same way: pads on, 12-lead ECG, call your senior early; unstable means a synchronised shock."},
{id:"tc4",g:"T",p:1,s:"a",t:"Narrow regular tachycardia, stable: what is the treatment sequence and doses?",k:"Valsalva, then adenosine 6 mg, then 12 mg (flush at least 20 mL), then verapamil 2.5-5 mg or diltiazem 15-20 mg if adenosine is unsuitable."},
{id:"tc8",g:"T",p:2,s:"a",t:"How do you do the modified Valsalva, and how well does it work?",k:"Strain into a 10 mL syringe for 15 seconds, then lie flat with legs raised 45 degrees for 15 seconds. Converts about 43% vs 5-20% for standard Valsalva."},
{id:"tc9",g:"T",p:2,s:"a",t:"Narrow irregular (AF), stable: which drugs and doses, and when can you not cardiovert?",k:"Metoprolol 5 mg IV (not with wheeze or decompensated heart failure) or digoxin 250-500 mcg. Over 48 hours: no cardioversion unless anticoagulated or TOE clear."},
{id:"tc5",g:"T",p:1,s:"a",t:"Wide regular tachycardia: what do you treat it as, which drug and dose, and what must you never give?",k:"Treat it as VT. Amiodarone 300 mg over 20-60 minutes then 900 mg over 24 hours. Never verapamil or diltiazem."},
{id:"tc6",g:"T",p:1,s:"a",t:"Torsades: what do you stop, correct and give (magnesium dose), what do you avoid, and what if unstable?",k:"Stop QT drugs, correct potassium, magnesium 5 mmol IV over 10 minutes (may repeat once), then 20 mmol over 4 hours. Avoid amiodarone. Adverse signs: shock. The US page's '2-4 mg' looks like a typo for grams."},
{id:"tc2",g:"T",p:1,s:"a",t:"Tachycardia: if the shock fails, what do you give and then do?",k:"Amiodarone 300 mg IV over 10-20 minutes, repeat the shock, then 900 mg over 24 hours."},
{id:"tc12",g:"T",p:3,s:"p",t:"Sedation for cardioversion: what does the US page suggest, and what does ANZCOR say?",k:"The US page suggests fentanyl 50 mcg and midazolam 1-2 mg. ANZCOR names no drug or dose: use your protocol and senior or anaesthetic help."},
{id:"tc13",g:"T",p:3,s:"p",t:"What is the respiratory support ladder, and when BiPAP vs CPAP?",k:"Non-rebreather, then HFNC, then NIPPV (BiPAP for COPD, CPAP for heart failure), then intubate. Watch PaCO2 and pH."}
], sg: [
{id:"tcs1",g:"T",p:1,s:"p",t:"Adenosine: what side effects do you warn about, and when do you avoid it?",k:"Brief chest tightness and a pause are expected; warn the patient. Avoid in pre-excited AF. (My suggestion from standard teaching.)"},
{id:"tcs3",g:"T",p:3,s:"a",t:"VT during acute MI: when is lignocaine reasonable (ANZCOR)?",k:"ANZCOR calls it reasonable for stable sustained monomorphic VT with ischaemia, and gives no dose."},
{id:"tcs4",g:"R",p:1,s:"p",t:"What does a wide QRS mean, and what are the three reasons for it?",k:"The signal took a slow route through muscle. Three reasons: the beat starts in the ventricle (VT), a fast wire is blocked (bundle branch block or aberrancy), or the signal came down an accessory pathway (pre-excitation). Wide tells you the route was slow, not the cause. (My suggestion.)"},
{id:"tcs5",g:"R",p:1,s:"p",t:"Wide tachycardia: what does regular vs irregular suggest?",k:"Wide, regular, same shape every beat: think VT (one focus firing like a metronome). Wide, irregular, shape changing beat to beat: think AF down an accessory pathway or AF with block. (My suggestion.)"},
{id:"tcs6",g:"A",p:1,s:"p",t:"What are the clues for pre-excited AF?",k:"Young patient, past episodes of fast palpitations, old ECG with a delta wave, irregular rate over 200 with a QRS width that changes beat to beat. Find his old ECGs. (My suggestion.)"},
{id:"tcs2",g:"F",p:2,s:"p",t:"After a tachycardia converts: what do you do?",k:"Repeat the 12-lead (delta wave?), check K and Mg, find the cause, tell your senior or cardiology. (My suggestion.)"}
]},
"respiratory-distress-rapid-response": { items: [
{id:"rd1",g:"R",p:1,s:"g",t:"Respiratory distress: what do you look at first, and what do you do straight away?",k:"Talking? Rate, effort, SpO2, pulse, BP, drowsiness. Sit up, monitor, IV access and call for help early."},
{id:"rd2",g:"R",p:1,s:"g",t:"What are the oxygen targets for most adults and for CO2 retainers, and when is oxygen not needed?",k:"Most acutely unwell adults 92 to 96%; COPD or CO2 retainers 88 to 92% (TSANZ). Oxygen is not for breathlessness without hypoxia."},
{id:"rd3",g:"R",p:2,s:"g",t:"Stridor or facial swelling: what do you give, and who do you call?",k:"Upper airway obstruction or anaphylaxis: IM adrenaline, call anaesthetics early."},
{id:"rd4",g:"R",p:1,s:"g",t:"How do you diagnose tension pneumothorax, and do you wait for imaging?",k:"Breathless, absent air entry one side, low BP, high airway pressures: decompress without waiting for imaging."},
{id:"rd5",g:"A",p:1,s:"g",t:"How do you read a gas: type 1 vs type 2 failure, and acute vs chronic?",k:"Type 1: low O2 with normal or low CO2. Type 2: high CO2. High CO2 with low pH is acute; a high bicarbonate means chronic."},
{id:"rd6",g:"A",p:2,s:"g",t:"Venous vs arterial gas: what can a venous gas tell you, and what can't it?",k:"A venous gas gives pH and an approximate CO2 but cannot assess oxygenation (MJA 2015)."},
{id:"rd7",g:"A",p:2,s:"g",t:"Respiratory distress: which bedside tests in the first minutes?",k:"12-lead ECG, glucose, bloods, chest X-ray or bedside ultrasound."},
{id:"rd8",g:"T",p:1,s:"g",t:"Respiratory distress: what is the first move for wheeze, oedema, anaphylaxis and opioid excess?",k:"Wheeze: bronchodilator. Oedema: sit up and CPAP. Anaphylaxis: IM adrenaline. Opioid excess: support breathing and titrated naloxone per protocol."},
{id:"rd9",g:"T",p:1,s:"g",t:"What is the oxygen ladder, and how do you climb it?",k:"Cannula, Venturi or simple mask, non-rebreather, high-flow, CPAP or BiPAP, intubation. Move up one rung at a time."},
{id:"rd10",g:"T",p:1,s:"g",t:"Which failure does CPAP treat, and which does BiPAP treat?",k:"CPAP: pulmonary oedema (low oxygen). BiPAP: hypercapnic acidosis (high CO2 with a low pH). Match the support to the type of failure."},
{id:"rd15",g:"T",p:1,s:"p",t:"Why use a Venturi mask for CO2 retainers?",k:"It gives a fixed oxygen percentage (24% or 28%) however they breathe, so you can hit 88 to 92% without overshooting. A simple mask or non-rebreather varies or gives too much. (Standard teaching.)"},
{id:"rd16",g:"T",p:1,s:"p",t:"CPAP vs BiPAP: what does each pressure do, and which problem does each fix?",k:"CPAP is one steady pressure that keeps air spaces open: for low oxygen from pulmonary oedema or pneumonia. BiPAP adds a push on each breath in: for a high CO2 with a low pH. (Standard teaching.)"},
{id:"rd17",g:"T",p:2,s:"p",t:"Why do low-flow devices give a varying oxygen percentage, and how is high-flow different?",k:"A breathless patient breathes in faster than a cannula or mask delivers, so they fill the gap from room air and the real percentage varies. High-flow nasal oxygen meets their flow, so the setting is what they get."},
{id:"rd11",g:"C",p:1,s:"g",t:"Why must you not sedate a breathless, agitated patient?",k:"Anxiety and agitation are often hypoxia or high CO2."},
{id:"rd12",g:"C",p:2,s:"g",t:"Sudden low saturation, clear chest, recent surgery: what do you think of first?",k:"Think pulmonary embolism before pneumonia."},
{id:"rd13",g:"F",p:1,s:"g",t:"Respiratory distress: when do you call ICU outreach, and what do you check early?",k:"Drowsy, silent chest, rising CO2 or falling pH, hypotension, or oxygen need rising. Check treatment limits early."},
{id:"rd14",g:"F",p:2,s:"g",t:"How do you hand over a breathless patient in 20 seconds?",k:"Who, what you see, what you think, what you have done, what you need. Include the gas."}
], sg: [
{id:"rds1",g:"A",p:2,s:"g",t:"Deep, fast breathing with a clear chest: what do you look for, and what causes it?",k:"Kussmaul breathing with a clear chest: look for metabolic acidosis (DKA, sepsis, toxins)."}
]},
"asthma-exacerbation": { items: [
{id:"as1",g:"R",p:1,s:"g",t:"Asthma: how do you grade severity as mild to moderate, severe or life-threatening?",k:"Grade by the worst feature. Mild to moderate: full sentences, SpO2 over 94%. Severe: cannot finish a sentence, accessory muscles, SpO2 94% or below. Life-threatening: drowsy, exhausted, cyanosed, poor effort or SpO2 under 92%."},
{id:"as2",g:"R",p:1,s:"g",t:"Asthma with a silent chest, drowsy or exhausted: what does it mean, and who do you call?",k:"Life-threatening: little air is moving. Call ICU and your senior."},
{id:"as3",g:"A",p:2,s:"g",t:"Asthma: which causes or complications do you look for?",k:"Pneumothorax if suddenly worse or unequal air entry, anaphylaxis, pneumonia, beta-blocker or NSAID."},
{id:"as4",g:"A",p:2,s:"g",t:"Asthma: is a chest X-ray routine, and when do you do one?",k:"Not routine. Only if you suspect pneumothorax or pneumonia."},
{id:"as5",g:"T",p:1,s:"g",t:"Mild to moderate asthma: what salbutamol dose, by what device, and how often?",k:"4 to 12 puffs (100 micrograms each) by pMDI and spacer; repeat every 20 minutes in the first hour if needed, then every 4 to 6 hours."},
{id:"as6",g:"T",p:1,s:"g",t:"Severe asthma: what salbutamol and ipratropium doses, and how often?",k:"12 puffs by spacer every 20 minutes in the first hour (or a 5 mg nebule if no spacer) plus ipratropium 8 puffs (21 micrograms each) every 20 minutes; then 4 to 6 hourly."},
{id:"as7",g:"T",p:1,s:"g",t:"Life-threatening asthma: what bronchodilators, how given, and where does the patient go?",k:"Continuous nebulisation: 2 x 5 mg salbutamol nebules, oxygen-driven, with ipratropium 500 micrograms every 20 minutes for the first hour. Immediate transfer to higher-level care."},
{id:"as8",g:"T",p:1,s:"g",t:"Asthma: when do you start oxygen, and what is the target?",k:"Start if SpO2 under 92%. Target 92 to 96%, or 88 to 92% if CO2 retention is a risk."},
{id:"as9",g:"T",p:1,s:"g",t:"Asthma: what oral steroid, what dose, when, and for how long?",k:"Oral prednisolone early. Australian Prescriber: 50 mg first dose then 25 mg twice daily, about 7 to 10 days. Confirm in your hospital protocol."},
{id:"as10",g:"C",p:1,s:"g",t:"Breathless asthmatic: what does a normal or rising CO2 mean?",k:"They are tiring. In a breathless asthmatic, a normal CO2 is not reassuring."},
{id:"as11",g:"C",p:1,s:"g",t:"Asthma: when is IV magnesium used, and who decides?",k:"A senior decision: IV magnesium for severe attacks that are not responding; dose per your hospital protocol (not verified here)."},
{id:"as12",g:"C",p:1,s:"g",t:"Asthma: can you sedate a tiring patient?",k:"Never. Benzodiazepines and opioids can precipitate respiratory arrest in a tiring asthmatic."},
{id:"as13",g:"C",p:1,s:"g",t:"Asthma suddenly worse with one side silent: what do you think of, and what do you do?",k:"Tension pneumothorax: absent air entry on one side, hypotension, neck veins. Decompress; do not send for an X-ray first."},
{id:"as14",g:"F",p:1,s:"g",t:"Asthma discharge: what must be in place?",k:"Never discharge on a reliever alone. Preventer with an inhaled steroid, written action plan, spacer technique, GP review within a few days."},
{id:"as15",g:"F",p:2,s:"g",t:"Acute asthma: when do you reassess, and when do you escalate?",k:"At 20 minutes, one hour and after each change. Not improving at one hour: escalate."}
], sg: [
{id:"ass1",g:"T",p:3,s:"g",t:"Asthma in children: which guideline for dosing?",k:"Use the RCH guideline for paediatric dosing, not the adult page."}
]},
"copd-exacerbation": { items: [
{id:"co1",g:"R",p:1,s:"g",t:"What defines a COPD flare, and what other causes do you look for?",k:"More breathless, more sputum, purulent sputum. Infection is common, but look for heart failure, pneumonia, pneumothorax, PE and arrhythmia."},
{id:"co2",g:"R",p:1,s:"g",t:"COPD flare: what do you ask about early?",k:"Treatment limits: is ICU or intubation appropriate for this patient?"},
{id:"co3",g:"A",p:1,s:"g",t:"COPD flare: when do you do an arterial gas, and what do you look at?",k:"If drowsy, severe or low saturation. Look at pH and CO2 before and after oxygen changes."},
{id:"co4",g:"A",p:2,s:"g",t:"COPD flare: which tests?",k:"Chest X-ray, ECG, bloods, sputum culture if purulent; troponin and BNP if unclear."},
{id:"co5",g:"T",p:1,s:"g",t:"COPD flare: what oxygen target, by which devices, and why avoid excess?",k:"88 to 92%. Nasal prongs 0.5 to 2 L/min or Venturi 24% or 28%. Excess oxygen can worsen hypercapnia."},
{id:"co6",g:"T",p:1,s:"g",t:"COPD flare: what bronchodilator doses, by spacer and by nebuliser?",k:"Salbutamol by spacer 400 to 800 micrograms or nebulised 2.5 to 5 mg; ipratropium by spacer 80 micrograms or nebulised 500 micrograms; titrate hourly to six-hourly."},
{id:"co7",g:"T",p:1,s:"g",t:"COPD flare: what prednisolone dose, and for how long?",k:"Prednisolone 40 to 50 mg daily. NSW ACI: up to two weeks is adequate; shorter courses are common. Follow your protocol."},
{id:"co8",g:"T",p:2,s:"g",t:"COPD flare: when do you give an antibiotic, and which?",k:"If the sputum is purulent. Cover typical and atypical organisms; agent and dose per eTG and your hospital protocol."},
{id:"co9",g:"T",p:1,s:"g",t:"COPD flare: when do you consider NIV?",k:"Respiratory acidosis (NSW ACI: pH under 7.3 or worsening; many protocols start under 7.35 with a raised CO2), drowsiness, severe breathlessness, persistent hypoxaemia."},
{id:"co10",g:"C",p:1,s:"g",t:"COPD patient drowsy on high oxygen with a slow rate: what is happening, and what do you do?",k:"Over-oxygenation. Reduce to the target and check a gas."},
{id:"co11",g:"C",p:1,s:"g",t:"COPD on NIV not improving at one hour: what do you do?",k:"Call ICU and discuss intubation within agreed limits."},
{id:"co12",g:"C",p:2,s:"g",t:"Wheeze not responding to COPD treatment: what else could it be?",k:"Not always COPD: think heart failure, pneumothorax, PE and arrhythmia."},
{id:"co13",g:"F",p:1,s:"g",t:"COPD flare: what are the admission criteria?",k:"Marked symptoms plus failure at home, loss of mobility, cannot eat or sleep, altered mental state, worsening hypoxaemia, right heart failure or new arrhythmia."},
{id:"co14",g:"F",p:2,s:"g",t:"COPD: what must happen before discharge?",k:"Inhaler technique, preventer plan, smoking cessation, vaccines, pulmonary rehabilitation, written action plan and early review."}
], sg: [
{id:"cos1",g:"C",p:2,s:"g",t:"COPD CO2 retainer: what drives the nebuliser, and how do you give oxygen?",k:"Nebulise with air, and give controlled oxygen by nasal prongs alongside (standard teaching)."}
]},
"community-acquired-pneumonia": { items: [
{id:"pn1",g:"R",p:1,s:"g",t:"How does pneumonia present, and what are its mimics?",k:"Fever, cough, focal signs, a new shadow on X-ray. Mimics: heart failure, PE, aspiration, lung cancer and TB."},
{id:"pn2",g:"R",p:1,s:"g",t:"Pneumonia: which red flags mean hospital?",k:"RR over 22, confusion, HR over 100, SBP under 90, SpO2 under 92%, multilobar X-ray, vomiting, no social support, unstable comorbidities."},
{id:"pn3",g:"A",p:1,s:"g",t:"Pneumonia: how do CURB-65 and CORB guide where to treat?",k:"CURB-65: above 1 inpatient; above 2 consider HDU or ICU. CORB: confusion, SaO2 90% or below, RR 30 or more, low BP."},
{id:"pn4",g:"A",p:1,s:"g",t:"Pneumonia: which tests before antibiotics?",k:"Chest X-ray, bloods, blood cultures (if no delay), sputum culture. Urine antigens and viral PCR if admitted and sick."},
{id:"pn5",g:"T",p:1,s:"g",t:"Mild CAP: which antibiotic, what dose, alternatives, and how long (TG v16)?",k:"Amoxicillin 1 g orally 8-hourly; doxycycline 100 mg 12-hourly or clarithromycin 500 mg 12-hourly if atypical suspected or penicillin allergy; 5 to 7 days (TG v16)."},
{id:"pn6",g:"T",p:1,s:"g",t:"Moderate CAP: where is it treated, which antibiotics, and when do you step down?",k:"Admit. IV benzylpenicillin 1.2 g 6-hourly plus doxycycline; step down to oral amoxicillin when improving (2011 summary; check eTG)."},
{id:"pn7",g:"T",p:1,s:"g",t:"Severe CAP: which antibiotics, where, and when do you call ID?",k:"Ceftriaxone 1 g IV daily plus azithromycin 500 mg IV daily; HDU or ICU; ID if allergic, a returned traveller or Staph aureus risk (2011 summary; check eTG)."},
{id:"pn8",g:"T",p:2,s:"g",t:"Pneumonia: when do you give oxygen?",k:"Give if SpO2 under 92%, to the target range."},
{id:"pn9",g:"C",p:1,s:"g",t:"Pneumonia with sepsis: what are the signs, and what do you do?",k:"Shock, high lactate or organ dysfunction: sepsis pathway and antibiotics without delay."},
{id:"pn10",g:"C",p:1,s:"g",t:"Pneumonia not responding at 48 hours: what do you do?",k:"Reassess, repeat the X-ray and cultures; in mild CAP add doxycycline or clarithromycin."},
{id:"pn11",g:"C",p:1,s:"g",t:"Pneumonia not improving at 5 days: what do you look for, and with what?",k:"Look for empyema or lung abscess with ultrasound or CT."},
{id:"pn12",g:"F",p:2,s:"g",t:"Pneumonia: when do you step down to oral antibiotics?",k:"When clinically improving; complete the course."},
{id:"pn13",g:"F",p:2,s:"g",t:"After pneumonia: when do you repeat the chest X-ray, and for whom?",k:"At about 6 weeks, if the first film was abnormal (TG via Medicine Today)."},
{id:"pn14",g:"F",p:3,s:"g",t:"Pneumonia: what do you offer before discharge?",k:"Vaccines and smoking cessation."}
], sg: [
{id:"pns1",g:"A",p:2,s:"g",t:"CAP with penicillin allergy: what do you do for immediate vs non-immediate reactions?",k:"Immediate reaction: discuss with ID. Non-immediate: ceftriaxone may be possible (2011 summary)."}
]},
"pneumothorax": { items: [
{id:"px1",g:"R",p:1,s:"g",t:"How do you diagnose tension pneumothorax, and do you wait for imaging?",k:"Clinically: shock, severe breathlessness, absent air entry one side, high airway pressures if ventilated. Do not wait for imaging."},
{id:"px2",g:"R",p:2,s:"g",t:"What are the types of pneumothorax?",k:"Primary (young, tall, thin), secondary (lung disease), traumatic, iatrogenic, tension."},
{id:"px3",g:"A",p:1,s:"g",t:"How do you confirm a pneumothorax?",k:"Upright chest X-ray; bedside ultrasound (no lung sliding, lung point); CT if unclear and stable."},
{id:"px4",g:"T",p:1,s:"g",t:"Tension pneumothorax: how do you decompress (needle, site), and what if no improvement?",k:"Decompress, then drain. 14 or 16 gauge cannula; adult site per your protocol (the Australian paediatric guideline uses the second intercostal space, mid-clavicular line, 90 degrees); a second attempt about 1 cm away if no improvement."},
{id:"px5",g:"T",p:1,s:"g",t:"Small primary pneumothorax with little breathlessness: what do you do?",k:"Observe; discharge with early review if they can come back easily (NSW ACI)."},
{id:"px6",g:"T",p:1,s:"g",t:"Large or symptomatic primary pneumothorax, stable: what do you do, and how?",k:"Aspirate: 14 to 16 gauge; stop at resistance, excessive cough or 2.5 L; repeat X-ray; 2 to 6 hours observation if symptom-free."},
{id:"px7",g:"T",p:1,s:"g",t:"Failed aspiration or a secondary pneumothorax: what do you do?",k:"Small-bore drain and admit. All secondary pneumothoraces are admitted; large or symptomatic ones get a small-bore drain."},
{id:"px8",g:"T",p:2,s:"g",t:"Chest drain: where is the site, and where do you cut to avoid the nerve and vessels?",k:"Fifth intercostal space, anterior to the mid-axillary line; incision above the lower rib to avoid the nerve and vessels (PCH guideline)."},
{id:"px9",g:"C",p:1,s:"g",t:"Chest drain: do you use routine suction, and why not?",k:"No routine suction: it risks re-expansion pulmonary oedema (NSW ACI)."},
{id:"px10",g:"C",p:1,s:"g",t:"Bubbling chest drain: can you clamp it, and where does the bottle go?",k:"Never clamp a bubbling drain. Keep the bottle below chest level and upright."},
{id:"px11",g:"C",p:1,s:"g",t:"Chest drain stopped swinging and the patient is worse: what do you check and do?",k:"Check for a kink, blockage or disconnection; X-ray; call your senior. A blocked tube can lead to tension."},
{id:"px12",g:"C",p:2,s:"g",t:"Ventilated patient with a sudden rise in airway pressure and low BP: what do you think of?",k:"A sudden rise in airway pressure with hypotension: think tension pneumothorax."},
{id:"px13",g:"F",p:2,s:"g",t:"When do you remove a chest drain, and what if the leak persists?",k:"When the lung is up and there is no leak. A persistent leak for days: involve cardiothoracic surgery."},
{id:"px14",g:"F",p:2,s:"g",t:"After a pneumothorax: what advice do you give?",k:"Stop smoking; recurrence is common; flying and diving advice per your respiratory team."}
], sg: [
{id:"pxs1",g:"T",p:3,s:"g",t:"Pneumothorax: what can oxygen do, and what is the caution in CO2 retainers?",k:"High-flow oxygen may speed resolution (NSW ACI); use the controlled target in CO2 retainers."}
]}
};
